import pandas as pd

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    """
    Multi-step partition refresh: DELETE whole arriving partitions then INSERT.

    Step 1: Create STG_NEW by aggregating inbound data
    Step 2: Delete from TARGET_SNAPSHOT all rows matching arriving partitions
    Step 3: Insert STG_NEW rows into TARGET_SNAPSHOT
    """

    inbound = inputs.get('inbound', pd.DataFrame())
    target_snapshot = inputs.get('target_snapshot', pd.DataFrame())

    # Step 1: CREATE STG_NEW
    # Filter for qty > 0, then aggregate by product_id and batch_date
    if len(inbound) > 0:
        stg_new = inbound[inbound['qty'] > 0].groupby(
            ['product_id', 'batch_date'],
            as_index=False
        ).agg({
            'qty': 'sum',
            'unit_cost': 'max'
        }).rename(columns={
            'qty': 'total_qty',
            'unit_cost': 'max_unit_cost'
        })
    else:
        stg_new = pd.DataFrame(columns=['product_id', 'batch_date', 'total_qty', 'max_unit_cost'])

    # Step 2: DELETE FROM TARGET_SNAPSHOT
    # Get distinct batch_dates from STG_NEW
    if len(stg_new) > 0:
        arriving_partitions = stg_new['batch_date'].unique()
        # Delete rows where batch_date is in arriving_partitions
        target_snapshot = target_snapshot[
            ~target_snapshot['batch_date'].isin(arriving_partitions)
        ].copy()

    # Step 3: INSERT INTO TARGET_SNAPSHOT
    # Append STG_NEW rows to TARGET_SNAPSHOT
    if len(stg_new) > 0:
        target_snapshot = pd.concat(
            [target_snapshot, stg_new],
            ignore_index=True
        )

    # Ensure column order and types match expected output
    if len(target_snapshot) > 0:
        target_snapshot = target_snapshot[['product_id', 'batch_date', 'total_qty', 'max_unit_cost']]
    else:
        target_snapshot = pd.DataFrame(columns=['product_id', 'batch_date', 'total_qty', 'max_unit_cost'])

    return {'target_snapshot': target_snapshot}
